import React, { useState, useEffect } from 'react';
import './App.css';

// ============================================
// API CONFIGURATION
// ============================================
// This is the address of the backend server
// All API calls will go to this address
const API_BASE = 'http://localhost:5000/api/user';

// ============================================
// KENYAN COUNTIES DATA
// ============================================
// These are all 47 counties in Kenya for the dropdown
const KENYAN_COUNTIES = [
  'Baringo', 'Bomet', 'Bungoma', 'Busia', 'Elgeyo Marakwet', 'Embu', 'Garissa', 
  'Homa Bay', 'Isiolo', 'Kajiado', 'Kakamega', 'Kericho', 'Kiambu', 'Kilifi', 
  'Kirinyaga', 'Kisii', 'Kisumu', 'Kitui', 'Kwale', 'Laikipia', 'Lamu', 
  'Machakos', 'Makueni', 'Mandera', 'Marsabit', 'Meru', 'Migori', 'Mombasa', 
  'Muranga', 'Nairobi', 'Nakuru', 'Nandi', 'Narok', 'Nyamira', 'Nyandarua', 
  'Nyeri', 'Samburu', 'Siaya', 'Taita Taveta', 'Tana River', 'Tharaka Nithi', 
  'Trans Nzoia', 'Turkana', 'Uasin Gishu', 'Vihiga', 'Wajir', 'West Pokot'
];

// ============================================
// KENYAN TOWNS DATA
// ============================================
// Each county has a list of towns
// When you select a county, only towns from that county appear
const KENYAN_TOWNS = {
  'Baringo': ['Kabarnet', 'Eldama Ravine', 'Mogotio', 'Marigat'],
  'Bomet': ['Bomet', 'Sotik', 'Chepalungu', 'Konoin'],
  'Bungoma': ['Bungoma', 'Webuye', 'Kimilili', 'Sirisia', 'Tongaren'],
  'Busia': ['Busia', 'Nambale', 'Malaba', 'Matayos'],
  'Elgeyo Marakwet': ['Iten', 'Tambach', 'Kapchorwa'],
  'Embu': ['Embu', 'Runyenjes', 'Siakago'],
  'Garissa': ['Garissa', 'Masalani', 'Habaswein'],
  'Homa Bay': ['Homa Bay', 'Mbita', 'Oyugis', 'Kendu Bay'],
  'Isiolo': ['Isiolo', 'Garbatulla', 'Merti'],
  'Kajiado': ['Kajiado', 'Ngong', 'Ongata Rongai', 'Kitengela', 'Kiserian'],
  'Kakamega': ['Kakamega', 'Mumias', 'Butere', 'Khwisero', 'Navakholo'],
  'Kericho': ['Kericho', 'Litein', 'Bureti', 'Kipkelion'],
  'Kiambu': ['Kiambu', 'Thika', 'Ruiru', 'Kikuyu', 'Limuru', 'Githunguri', 'Lari', 'Gatundu'],
  'Kilifi': ['Kilifi', 'Malindi', 'Watamu', 'Mtwapa', 'Bamburi'],
  'Kirinyaga': ['Kerugoya', 'Kutus', 'Sagana', 'Wanguru'],
  'Kisii': ['Kisii', 'Ogembo', 'Nyamira', 'Keroka'],
  'Kisumu': ['Kisumu', 'Ahero', 'Muhoroni', 'Maseno'],
  'Kitui': ['Kitui', 'Mwingi', 'Mutomo', 'Kyuso'],
  'Kwale': ['Kwale', 'Ukunda', 'Msambweni', 'Lunga Lunga'],
  'Laikipia': ['Nanyuki', 'Rumuruti', 'Nyahururu', 'Ol Kalou'],
  'Lamu': ['Lamu', 'Mpeketoni', 'Witu'],
  'Machakos': ['Machakos', 'Athi River', 'Mavoko', 'Kangundo', 'Tala'],
  'Makueni': ['Wote', 'Makindu', 'Kilungu', 'Emali'],
  'Mandera': ['Mandera', 'Rhamu', 'El Wak', 'Takaba'],
  'Marsabit': ['Marsabit', 'Moyale', 'Loiyangalani', 'North Horr'],
  'Meru': ['Meru', 'Maua', 'Chuka', 'Nkubu', 'Timau'],
  'Migori': ['Migori', 'Kehancha', 'Rongo', 'Awendo'],
  'Mombasa': ['Mombasa', 'Nyali', 'Bamburi', 'Kisauni', 'Likoni'],
  'Muranga': ['Muranga', 'Kangema', 'Kigumo', 'Kenol'],
  'Nairobi': ['Nairobi', 'Kasarani', 'Embakasi', 'Karen', 'Langata', 'Westlands', 'Parklands', 'Kilimani', 'Hurlingham', 'Lavington'],
  'Nakuru': ['Nakuru', 'Naivasha', 'Gilgil', 'Njoro', 'Molo', 'Rongai', 'Subukia'],
  'Nandi': ['Kapsabet', 'Nandi Hills', 'Kilibwoni', 'Tinderet'],
  'Narok': ['Narok', 'Kilgoris', 'Mulot', 'Mara', 'Ololulunga'],
  'Nyamira': ['Nyamira', 'Keroka', 'Manga', 'Ekerenyo'],
  'Nyandarua': ['Ol Kalou', 'Nyahururu', 'Ndaragwa', 'Kinangop'],
  'Nyeri': ['Nyeri', 'Karatina', 'Othaya', 'Kiganjo', 'Mweiga'],
  'Samburu': ['Maralal', 'Baragoi', 'Archer\'s Post', 'Wamba'],
  'Siaya': ['Siaya', 'Bondo', 'Ugunja', 'Yala', 'Rarieda'],
  'Taita Taveta': ['Voi', 'Wundanyi', 'Taveta', 'Mwatate'],
  'Tana River': ['Hola', 'Garsen', 'Madogo', 'Bura'],
  'Tharaka Nithi': ['Chuka', 'Kathwana', 'Makutano', 'Marimanti'],
  'Trans Nzoia': ['Kitale', 'Kiminini', 'Endebess', 'Sinyereri'],
  'Turkana': ['Lodwar', 'Lokichoggio', 'Lokitaung', 'Kakuma', 'Eliye Springs'],
  'Uasin Gishu': ['Eldoret', 'Kapsabet', 'Turbo', 'Moiben', 'Kesses'],
  'Vihiga': ['Vihiga', 'Mbale', 'Sabatia', 'Luanda'],
  'Wajir': ['Wajir', 'Bute', 'Habaswein', 'Eldas'],
  'West Pokot': ['Kapenguria', 'Kacheliba', 'Ortum', 'Kongelai']
};

function App() {
  // ============================================
  // WHAT IS STATE?
  // State is like the app's memory - it stores data that changes
  // When state changes, React automatically updates what you see on screen
  // ============================================

  // Registration Flow State
  // currentStep: 0=Activation, 1=Registration, 2=Profile Complete, 3=Description, 4=Done
  const [currentStep, setCurrentStep] = useState(0);
  const [completedSteps, setCompletedSteps] = useState(new Set());
  const [formData, setFormData] = useState({});
  const [isLoading, setIsLoading] = useState(false);
  const [responseMessage, setResponseMessage] = useState('');
  const [isSuccess, setIsSuccess] = useState(false);
  const [errorDetails, setErrorDetails] = useState('');

  // User Authentication State
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [currentUser, setCurrentUser] = useState(null); // This stores the logged-in user's data
  const [notifications, setNotifications] = useState([]);
  const [serverStatus, setServerStatus] = useState('checking');
  const [activationDone, setActivationDone] = useState(false);
  const [myPhone, setMyPhone] = useState('0712345678');
  const [isFirstTimeUser, setIsFirstTimeUser] = useState(true);
  const [showWelcomeBack, setShowWelcomeBack] = useState(false);

  // UI State
  const [registrationError, setRegistrationError] = useState('');
  const [userExistsError, setUserExistsError] = useState(false);
  const [showMainMenu, setShowMainMenu] = useState(false);
  const [registrationComplete, setRegistrationComplete] = useState(false);
  const [activationKeyword, setActivationKeyword] = useState('');
  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const [showSystemResponse, setShowSystemResponse] = useState(false);
  const [systemResponseMessage, setSystemResponseMessage] = useState('');
  const [showSuccessScreen, setShowSuccessScreen] = useState(false);
  const [successMessage, setSuccessMessage] = useState('');
  const [successTitle, setSuccessTitle] = useState('');
  const [isCompleteProfileStep, setIsCompleteProfileStep] = useState(false);
  const [showLogoutModal, setShowLogoutModal] = useState(false);

  // SMS Conversation (System Responses Only)
  const [smsConversation, setSmsConversation] = useState([]);

  // ============================================
  // MATCHING & DASHBOARD STATE
  // ============================================

  // Matching State
  const [matchSearchActive, setMatchSearchActive] = useState(false);
  const [matchResults, setMatchResults] = useState([]);
  const [matchOffset, setMatchOffset] = useState(0);
  const [totalMatches, setTotalMatches] = useState(0);
  const [selectedMatchDetails, setSelectedMatchDetails] = useState(null);
  const [showMatchDescription, setShowMatchDescription] = useState(false);
  const [consentRequest, setConsentRequest] = useState(null);

  // Dashboard State
  const [allMatches, setAllMatches] = useState([]);
  const [currentMatchIndex, setCurrentMatchIndex] = useState(0);
  const [incomingRequests, setIncomingRequests] = useState([]);
  const [currentRequestIndex, setCurrentRequestIndex] = useState(0);
  const [myMatches, setMyMatches] = useState([]);
  const [currentMatchListIndex, setCurrentMatchListIndex] = useState(0);
  const [activeTab, setActiveTab] = useState('discover');
  const [showProfile, setShowProfile] = useState(false);
  const [showMatchDetails, setShowMatchDetails] = useState(false);

  // CRITICAL: selectedMatch stores the person whose profile is being viewed
  // This should NEVER be set to the current user
  const [selectedMatch, setSelectedMatch] = useState(null);

  const [isSendingMessage, setIsSendingMessage] = useState(false);
  const [searchCriteria, setSearchCriteria] = useState({ 
    ageRange: '', town: '', county: '' 
  });
  const [isSearching, setIsSearching] = useState(false);
  const [hasMoreMatches, setHasMoreMatches] = useState(false);
  const [editProfileData, setEditProfileData] = useState({});
  const [showDescriptionModal, setShowDescriptionModal] = useState(false);
  const [descriptionData, setDescriptionData] = useState(null);

  // Chat State
  const [chatContacts, setChatContacts] = useState([]);
  const [chatMessages, setChatMessages] = useState({});
  const [newMessage, setNewMessage] = useState('');
  const [selectedChatContact, setSelectedChatContact] = useState(null);

  // Stats
  const [stats, setStats] = useState({
    totalMatches: 0,
    pendingRequests: 0,
    acceptedMatches: 0,
    unreadMessages: 0
  });

  // ============================================
  // SMS SYSTEM MESSAGES
  // ============================================
  const SYSTEM_MESSAGES = {
    activation: `Welcome to our dating service with 6000 potential dating partners!\n\nTo register SMS start#name#age#gender#county#town to 22141.\nE.g., start#John Doe#26#Male#Nakuru#Naivasha`,
    registrationSuccess: (name) => `Your profile has been created successfully ${name}.\n\nSMS details#levelOfEducation#profession#maritalStatus#religion#ethnicity to 22141.\nE.g. details#diploma#driver#single#christian#mijikenda`,
    detailsNotProvided: `You were registered for dating with your initial details.\n\nTo search for a MPENZI, SMS match#age#town to 22141\nE.g., match#23-25#Nairobi`,
    detailsProvided: `This is the last stage of registration. SMS a brief description of yourself to 22141 starting with the word MYSELF.\nE.g., MYSELF chocolate, lovely, sexy etc.`,
    selfDescriptionSuccess: `You are now registered for dating. To search for a MPENZI, SMS match#age#town to 22141 and meet the person of your dreams.\nE.g., match#23-25#Kisumu`,
    matchFound: (count, gender) => `We have ${count} ${gender} who match your choice! We will send you details of 3 of them shortly. To get more details about a ${gender.slice(0, -1)}, SMS her number e.g., 0722010203 to 22141`,
    matchList: (matches) => {
      return matches.map(m => `${m.name} aged ${m.age}, ${m.phone}`).join('\n') + 
             '\n\nSend NEXT to 22141 to receive details of the remaining ladies';
    },
    nextMatches: (matches) => {
      return matches.map(m => `${m.name} aged ${m.age}, ${m.phone}`).join('\n') + 
             '\n\nSend NEXT to 22141 to receive details of the remaining ladies';
    },
    userDetails: (user) => `${user.name} aged ${user.age}, ${user.county || 'N/A'} County, ${user.town || 'N/A'} town,\n${user.education || 'N/A'}, ${user.profession || 'N/A'}, ${user.marital_status || 'N/A'}, ${user.religion || 'N/A'}, ${user.ethnicity || 'N/A'}.\n\nSend DESCRIBE ${user.phone} to get more details about ${user.name}.`,
    interestNotification: (fromUser, toUser) => `Hi ${toUser.name}, a ${fromUser.gender || 'man'} called ${fromUser.name} is interested in you and requested your details.\nHe is aged ${fromUser.age} based in ${fromUser.town || 'N/A'}.\n\nDo you want to know more about him? Send YES to 22141`,
    userDescription: (user) => `${user.name} describes themselves as ${user.description || 'Not provided'}`,
    consentConfirmation: (fromUser) => `${fromUser.name} aged ${fromUser.age}, ${fromUser.county || 'N/A'} County, ${fromUser.town || 'N/A'} town,\n${fromUser.education || 'N/A'}, ${fromUser.profession || 'N/A'}, ${fromUser.marital_status || 'N/A'}, ${fromUser.religion || 'N/A'}, ${fromUser.ethnicity || 'N/A'}.\n\nSend DESCRIBE ${fromUser.phone} to get more details about ${fromUser.name}.`,
    interestSent: (name) => `Your interest request has been sent successfully to ${name}.\n\nThe other member will be notified.`,
    requestAccepted: (name) => `Congratulations! You have accepted ${name}'s request.\n\nYou may now begin chatting.`
  };

  // ============================================
  // SAMPLE DATA - Female Profiles (shown to men)
  // ============================================
  const SAMPLE_MATCHES = [
    { id: 1, phone: '0722010203', name: 'Lina Moraa', age: 29, town: 'Nairobi', county: 'Nairobi', profession: 'Nurse', education: 'Graduate', religion: 'Christian', ethnicity: 'Kikuyu', marital_status: 'single', description: 'Kind-hearted and adventurous. Loves hiking and reading.', gender: 'Female' },
    { id: 2, phone: '0701223344', name: 'Dorine Gakii', age: 26, town: 'Nakuru', county: 'Nakuru', profession: 'Teacher', education: 'Diploma', religion: 'Christian', ethnicity: 'Kamba', marital_status: 'single', description: 'Caring and dedicated. Loves children and education.', gender: 'Female' },
    { id: 3, phone: '0700112233', name: 'Aisha Bahati', age: 27, town: 'Mombasa', county: 'Mombasa', profession: 'Accountant', education: 'Graduate', religion: 'Muslim', ethnicity: 'Swahili', marital_status: 'single', description: 'Ambitious and hardworking. I love numbers.', gender: 'Female' },
    { id: 4, phone: '0722040506', name: 'Pamela Nafula', age: 26, town: 'Kisumu', county: 'Kisumu', profession: 'Engineer', education: 'Post Graduate', religion: 'Christian', ethnicity: 'Luo', marital_status: 'single', description: 'Tech enthusiast. Loves innovation and building solutions.', gender: 'Female' },
    { id: 5, phone: '0702556677', name: 'Maria Mwende', age: 28, town: 'Kasarani', county: 'Nairobi', profession: 'Nurse', education: 'Graduate', religion: 'Christian', ethnicity: 'Kamba', marital_status: 'single', description: 'Diligent, loving, dedicated and will make you tick.', gender: 'Female' },
    { id: 6, phone: '0708990011', name: 'Keziah Cheptab', age: 28, town: 'Eldoret', county: 'Uasin Gishu', profession: 'Doctor', education: 'Post Graduate', religion: 'Christian', ethnicity: 'Kalenjin', marital_status: 'single', description: 'Passionate about healthcare and community service.', gender: 'Female' }
  ];

  // ============================================
  // SAMPLE DATA - Male Profiles (shown to women)
  // ============================================
  const SAMPLE_MALE_MATCHES = [
    { id: 7, phone: '0711000001', name: 'John Mwangi', age: 30, town: 'Nairobi', county: 'Nairobi', profession: 'Engineer', education: 'Graduate', religion: 'Christian', ethnicity: 'Kikuyu', marital_status: 'single', description: 'Hardworking and ambitious. Love building things.', gender: 'Male' },
    { id: 8, phone: '0711000002', name: 'David Ochieng', age: 32, town: 'Kisumu', county: 'Kisumu', profession: 'Lawyer', education: 'Post Graduate', religion: 'Christian', ethnicity: 'Luo', marital_status: 'single', description: 'Passionate about justice and community service.', gender: 'Male' },
    { id: 9, phone: '0711000003', name: 'Peter Kiprop', age: 28, town: 'Eldoret', county: 'Uasin Gishu', profession: 'Businessman', education: 'Graduate', religion: 'Christian', ethnicity: 'Kalenjin', marital_status: 'single', description: 'Entrepreneurial spirit. Love meeting new people.', gender: 'Male' },
    { id: 10, phone: '0711000004', name: 'Samuel Mwangi', age: 27, town: 'Nakuru', county: 'Nakuru', profession: 'Developer', education: 'Graduate', religion: 'Christian', ethnicity: 'Kikuyu', marital_status: 'single', description: 'Tech enthusiast and code lover.', gender: 'Male' },
    { id: 11, phone: '0711000005', name: 'James Kamau', age: 31, town: 'Thika', county: 'Kiambu', profession: 'Architect', education: 'Post Graduate', religion: 'Christian', ethnicity: 'Kikuyu', marital_status: 'single', description: 'Creative designer. Love art and architecture.', gender: 'Male' },
    { id: 12, phone: '0711000006', name: 'Michael Omondi', age: 29, town: 'Mombasa', county: 'Mombasa', profession: 'Pilot', education: 'Graduate', religion: 'Christian', ethnicity: 'Luo', marital_status: 'single', description: 'Adventurous and love exploring new places.', gender: 'Male' }
  ];

  // ============================================
  // API CALL FUNCTION
  // ============================================
  const callApi = async (endpoint, method, body = null) => {
    try {
      const options = {
        method: method,
        headers: { 'Content-Type': 'application/json' }
      };
      if (body) {
        options.body = JSON.stringify(body);
      }
      const response = await fetch(`${API_BASE}${endpoint}`, options);
      const data = await response.json();
      console.log(`API ${method} ${endpoint}:`, data);
      return data;
    } catch (error) {
      console.error('API Error:', error);
      return null;
    }
  };

  // ============================================
  // LOAD SAVED STATE
  // ============================================
  useEffect(() => {
    try {
      const saved = localStorage.getItem('penziState');
      if (saved) {
        const parsed = JSON.parse(saved);

        if (parsed.currentUser && parsed.isLoggedIn) {
          setCurrentUser(parsed.currentUser);
          setIsLoggedIn(true);
          setAllMatches(parsed.allMatches || []);
          setIncomingRequests(parsed.incomingRequests || []);
          setMyMatches(parsed.myMatches || []);
          setChatContacts(parsed.chatContacts || []);
          setChatMessages(parsed.chatMessages || {});
          setActiveTab(parsed.activeTab || 'discover');
          setMyPhone(parsed.myPhone || '0712345678');
          setActivationDone(true);
          setShowWelcomeBack(true);
          setShowMainMenu(true);
          setMatchOffset(parsed.matchOffset || 0);
          setTotalMatches(parsed.totalMatches || 0);
          setSmsConversation(parsed.smsConversation || []);

          setTimeout(() => {
            addNotification(`👋 Welcome back, ${parsed.currentUser.name}!`);
          }, 500);

          setIsFirstTimeUser(false);
        } else {
          setCurrentStep(parsed.currentStep || 0);
          setCompletedSteps(new Set(parsed.completedSteps || []));
          setPhoneNumber(parsed.phoneNumber || '');
          setActivationDone(parsed.activationDone || false);
          setMyPhone(parsed.myPhone || '0712345678');
          setSmsConversation(parsed.smsConversation || []);
          if (parsed.currentUser) {
            setCurrentUser(parsed.currentUser);
          }
          setIsFirstTimeUser(true);
        }
      }
    } catch (e) {
      console.warn('Could not load saved state:', e);
      setIsFirstTimeUser(true);
    }
  }, []);

  // ============================================
  // SAVE STATE
  // ============================================
  useEffect(() => {
    try {
      const stateToSave = {
        currentStep,
        completedSteps: Array.from(completedSteps),
        currentUser,
        isLoggedIn,
        phoneNumber,
        activationDone,
        allMatches,
        incomingRequests,
        myMatches,
        chatContacts,
        chatMessages,
        activeTab,
        myPhone,
        showMainMenu,
        searchCriteria,
        matchOffset,
        totalMatches,
        smsConversation
