  /**
   * HANDLES EXPRESSING INTEREST IN A MATCH
   * 
   * HOW THIS WORKS:
   * 1. You click "Express Interest" on a match
   * 2. This function finds that match's data
   * 3. It sets selectedMatch to that match (NOT the current user)
   * 4. It opens the profile modal showing that match's profile
   * 5. From there, you can confirm or cancel
   * 
   * CRITICAL: selectedMatch should ALWAYS be the match, NEVER the current user
   */
  const handleExpressInterest = (targetPhone) => {
    // Step 1: Check if user's profile is complete
    const hasBasicProfile = currentUser?.name && currentUser?.age && currentUser?.gender;
    const hasDetails = currentUser?.education && currentUser?.profession && currentUser?.marital_status;

    if (!hasBasicProfile || !hasDetails) {
      addNotification('⚠️ Please complete your profile first before expressing interest.', 'warning');
      setShowProfile(true);
      setIsEditingProfile(true);
      return;
    }

    // Step 2: Find the match by phone number
    const allSampleMatches = [...SAMPLE_MATCHES, ...SAMPLE_MALE_MATCHES];
    const match = allMatches.find(m => m.phone === targetPhone) || 
                  matchResults.find(m => m.phone === targetPhone) ||
                  allSampleMatches.find(m => m.phone === targetPhone);

    if (!match) {
      addNotification('❌ Match not found.', 'error');
      return;
    }

    // Step 3: Gender check - only opposite gender
    const userGender = currentUser?.gender;
    if (userGender && match.gender) {
      const userGenderLower = userGender.toLowerCase();
      const matchGenderLower = match.gender.toLowerCase();

      if (userGenderLower === matchGenderLower) {
        addNotification('❌ You can only express interest in members of the opposite sex.', 'error');
        return;
      }

      if ((userGenderLower === 'male' && matchGenderLower !== 'female') ||
          (userGenderLower === 'female' && matchGenderLower !== 'male')) {
        addNotification('❌ You can only express interest in members of the opposite sex.', 'error');
        return;
      }
    }

    // Step 4: SHOW THE MATCH'S PROFILE
    // This is the important part - we set selectedMatch to the match, NOT the current user
    setSelectedMatch(match);
    setShowMatchDetails(true);
    addNotification(`👤 Viewing ${match.name}'s profile`);
  };

