              setActiveTab('matches');
            }}
          >
            💕 Matches
            <span className="nav-badge">{myMatches.length}</span>
          </button>
          <button 
            className={`nav-item ${activeTab === 'requests' ? 'active' : ''}`} 
            onClick={() => {
              setActiveTab('requests');
            }}
          >
            📬 Requests
            {hasRequests && <span className="nav-badge red">{incomingRequests.length}</span>}
          </button>
          <button 
            className={`nav-item ${activeTab === 'chat' ? 'active' : ''}`} 
            onClick={() => {
              setActiveTab('chat');
            }}
          >
            💬 Chat
            {hasChatContacts && <span className="nav-badge">{chatContacts.length}</span>}
          </button>
        </nav>

        <main className="dashboard-content">
          {activeTab === 'discover' && renderDiscoverTable()}
          {activeTab === 'matches' && renderMyMatchesTable()}
          {activeTab === 'requests' && renderRequestsTable()}
          {activeTab === 'chat' && (
            <div className="chat-container-whatsapp">
              {renderChat()}
            </div>
          )}
        </main>

        {showMatchDetails && renderProfileModal()}
        {showProfile && renderProfileDetails()}
        {renderDescriptionModal()}
      </div>
    );
  };

  // ============================================
  // REGISTRATION STEP RENDER FUNCTIONS
  // ============================================
  const renderRegistrationStep = () => {
    const step = currentStep + 1;
    const isLastStep = step === 4;
    const isStepCompleted = completedSteps.has(step - 1);

    const getFields = () => {
      if (step === 2) {
        return [
          { key: 'phone_number', label: '📱 Phone Number', placeholder: '0712345678', type: 'tel' },
          { key: 'name', label: '👤 Full Name', placeholder: 'Jamal Jalang\'o', type: 'text' },
          { key: 'age', label: '🎂 Age', placeholder: '29', type: 'number' },
          { key: 'gender', label: '⚤ Gender', type: 'select', options: ['Male', 'Female'] },
          { key: 'county', label: '📍 County', type: 'select-with-search', options: KENYAN_COUNTIES },
          { key: 'town', label: '🏙️ Town/City', type: 'select-with-search', options: [] }
        ];
      }
      if (step === 4) {
        return [
          { key: 'description', label: '💭 Describe yourself', placeholder: 'tall, dark and handsome', type: 'textarea' }
        ];
      }
      return [];
    };

    const getTownsForCounty = (county) => {
      return KENYAN_TOWNS[county] || [];
    };

    const handleCountyChange = (value) => {
      handleInputChange('county', value);
      handleInputChange('town', '');
    };

    const fields = getFields();
    const stepTitles = {
      2: 'Create Your Dating Profile',
      4: 'Tell Us About Yourself'
    };
    const stepIcons = {
      2: '📝',
      4: '💭'
    };

    const getStepDescription = () => {
      if (step === 2) {
        return 'Complete your registration details to start meeting compatible partners.';
      }
      if (step === 4) {
        return 'Tell us about yourself so we can find compatible matches.';
      }
      return '';
    };

    return (
      <div className="registration-container landscape">
        <div className="registration-card landscape-card">
          <div className="registration-header landscape-header">
            <span className="registration-icon">{stepIcons[step]}</span>
            <div className="header-text">
              <h1>{stepTitles[step]}</h1>
              <p className="subtitle">{getStepDescription()}</p>
            </div>
          </div>

          {activationDone && (
            <div className="progress-bar-container">
              <div className="progress-bar">
                <div className="progress-fill" style={{ width: `${getProgress()}%` }}></div>
              </div>
              <span className="progress-text">{getProgress()}% Complete • {completedSteps.size}/4</span>
            </div>
          )}

          {showSystemResponse && systemResponseMessage && renderSystemResponse()}

          <div className="step-info-card landscape-step-info">
            <div className="step-number">Step {step} of 4</div>
            <h2>{stepTitles[step]}</h2>
            <p>{getStepDescription()}</p>
          </div>

          {registrationError && !userExistsError && (
            <div className="registration-error">
              <span className="error-icon">⚠️</span>
              <span className="error-text">{registrationError}</span>
            </div>
          )}

          {fields.length > 0 && (
            <div className="registration-form landscape-form">
              {fields.map((field) => {
                if (field.key === 'town') {
                  const towns = getTownsForCounty(formData.county);
                  return (
                    <div key={field.key} className="input-group landscape-input-group">
                      <label>{field.label}</label>
                      <select
                        value={formData[field.key] || ''}
                        onChange={(e) => handleInputChange(field.key, e.target.value)}
                        className="input-field"
                        disabled={!formData.county}
                      >
                        <option value="">{formData.county ? 'Select Town' : 'Select County First'}</option>
                        {towns.map(town => (
                          <option key={town} value={town}>{town}</option>
                        ))}
                      </select>
                      {!formData.county && (
                        <small className="field-hint">Please select a county first to see towns</small>
                      )}
                    </div>
                  );
                }

                if (field.key === 'county') {
                  return (
                    <div key={field.key} className="input-group landscape-input-group">
                      <label>{field.label}</label>
                      <select
                        value={formData[field.key] || ''}
                        onChange={(e) => handleCountyChange(e.target.value)}
                        className="input-field"
                      >
                        <option value="">Select County</option>
                        {KENYAN_COUNTIES.map(county => (
                          <option key={county} value={county}>{county}</option>
                        ))}
                      </select>
                    </div>
                  );
                }

                if (field.type === 'select') {
                  return (
                    <div key={field.key} className="input-group landscape-input-group">
                      <label>{field.label}</label>
                      <select
                        value={formData[field.key] || ''}
                        onChange={(e) => handleInputChange(field.key, e.target.value)}
                        className="input-field"
                        required
                      >
                        <option value="">Select {field.label}</option>
                        {field.options.map(opt => (
                          <option key={opt} value={opt}>{opt}</option>
                        ))}
                      </select>
                    </div>
                  );
                }

                if (field.type === 'textarea') {
                  return (
                    <div key={field.key} className="input-group landscape-input-group full-width">
                      <label>{field.label}</label>
                      <textarea
                        value={formData[field.key] || ''}
                        onChange={(e) => handleInputChange(field.key, e.target.value)}
                        placeholder={field.placeholder}
                        className="textarea-field"
                        rows={4}
                        required
                      />
                    </div>
                  );
                }

                return (
                  <div key={field.key} className="input-group landscape-input-group">
                    <label>{field.label}</label>
                    <input
                      type={field.type || 'text'}
                      value={formData[field.key] || ''}
                      onChange={(e) => handleInputChange(field.key, e.target.value)}
                      placeholder={field.placeholder}
                      className="input-field"
                      required
                    />
                  </div>
                );
              })}
            </div>
          )}

          <div className="registration-actions landscape-actions">
            <button
              onClick={() => {
                const allFilled = fields.every(f => {
                  if (f.key === 'town' && !formData.county) return true;
                  return formData[f.key] && formData[f.key].trim() !== '';
                });
                if (!allFilled && step !== 4) {
                  addNotification('⚠️ Please fill in all fields.', 'warning');
                  return;
                }
                goToNextStep();
              }}
              disabled={isLoading}
              className="btn-register"
            >
              {isLoading ? '⏳ Processing...' : 'Continue'}
            </button>
            <button onClick={() => setShowLogoutModal(true)} className="btn-exit">
              Exit
            </button>
          </div>

          {isLastStep && isStepCompleted && (
            <div className="registration-complete-prompt">
              <p>🎉 Registration complete! You can now search for matches.</p>
            </div>
          )}

          {responseMessage && (
            <div className={`response-message ${isSuccess ? 'success' : 'error'}`}>
              {responseMessage}
            </div>
          )}

          <div className="registration-footer">
            <p>🔒 Your data is safe and private</p>
          </div>
        </div>
      </div>
    );
  };

  const renderCompleteProfile = () => {
    const profileFields = [
      { key: 'education_level', label: '🎓 Education Level', type: 'select', options: ['Primary', 'Secondary', 'Certificate', 'Diploma', 'Graduate', 'Post Graduate'] },
      { key: 'profession', label: '💼 Profession', placeholder: 'Accountant', type: 'text' },
      { key: 'marital_status', label: '💍 Marital Status', type: 'select', options: ['single', 'married', 'divorced', 'widowed', 'separated'] },
      { key: 'religion', label: '⛪ Religion', placeholder: 'Muslim', type: 'text' },
      { key: 'ethnicity', label: '🌍 Ethnicity', placeholder: 'Somali', type: 'text' }
    ];

    return (
      <div className="registration-container landscape">
        <div className="registration-card landscape-card">
          <div className="registration-header landscape-header">
            <span className="registration-icon">📋</span>
            <div className="header-text">
              <h1>Complete Your Dating Profile</h1>
              <p className="subtitle">Tell us more about yourself so we can find compatible matches.</p>
            </div>
          </div>

          {activationDone && (
            <div className="progress-bar-container">
              <div className="progress-bar">
                <div className="progress-fill" style={{ width: `${getProgress()}%` }}></div>
              </div>
              <span className="progress-text">{getProgress()}% Complete • {completedSteps.size}/4</span>
            </div>
          )}

          {showSystemResponse && systemResponseMessage && renderSystemResponse()}

          <div className="step-info-card landscape-step-info">
            <div className="step-number">Step 3 of 4</div>
            <h2>Complete Your Dating Profile</h2>
            <p>Tell us more about yourself so we can find compatible matches.</p>
          </div>

          {registrationError && (
            <div className="registration-error">
              <span className="error-icon">⚠️</span>
              <span className="error-text">{registrationError}</span>
            </div>
          )}

          <div className="registration-form landscape-form">
            {profileFields.map((field) => (
              <div key={field.key} className="input-group landscape-input-group">
                <label>{field.label}</label>
                {field.type === 'select' ? (
                  <select
                    value={formData[field.key] || ''}
                    onChange={(e) => handleInputChange(field.key, e.target.value)}
                    className="input-field"
                  >
                    <option value="">Select {field.label}</option>
                    {field.options.map(opt => (
                      <option key={opt} value={opt}>{opt}</option>
                    ))}
                  </select>
                ) : (
                  <input
                    type={field.type || 'text'}
                    value={formData[field.key] || ''}
                    onChange={(e) => handleInputChange(field.key, e.target.value)}
                    placeholder={field.placeholder}
                    className="input-field"
                  />
                )}
              </div>
            ))}
          </div>

          <div className="registration-actions landscape-actions">
            <button
              onClick={saveCompleteProfile}
              disabled={isLoading}
              className="btn-save-profile"
            >
              {isLoading ? '⏳ Saving...' : 'Continue'}
            </button>
            <button
              onClick={() => {
                addNotification('⏭️ Profile skipped. You can complete it later.');
                addToConversation('📱 You', 'details#(skipped)', false);
                addToConversation('🤖 System', SYSTEM_MESSAGES.detailsNotProvided, true);
                setSystemResponseMessage(SYSTEM_MESSAGES.detailsNotProvided);
                setShowSystemResponse(true);
                setCurrentStep(4);
                setIsCompleteProfileStep(false);
              }}
              className="btn-skip"
            >
              Skip
            </button>
            <button onClick={() => setShowLogoutModal(true)} className="btn-exit">
              Exit
            </button>
          </div>

          <div className="registration-footer">
            <p>🔒 Your data is safe and private</p>
          </div>
        </div>
      </div>
    );
  };

  const renderActivationPage = () => {
    return (
      <div className="activation-container">
        <div className="activation-card">
          <div className="activation-header">
            <span className="activation-icon">💑</span>
            <h1>Welcome to PENZI Dating Service</h1>
            <p className="subtitle">Find your perfect match</p>
          </div>

          <div className={`server-status ${serverStatus}`}>
            <span className="status-dot"></span>
            <span className="status-text">
              {serverStatus === 'connected' ? '✅ Server Connected' : 
               serverStatus === 'checking' ? '⏳ Checking...' : 
               '❌ Server Not Connected'}
            </span>
          </div>

          {showSystemResponse && systemResponseMessage && renderSystemResponse()}

          {!activationDone ? (
            <>
              <div className="activation-system-message">
                <div className="msg-title">📨 System Message</div>
                <div className="msg-body">Welcome to our dating service with over 6000 potential dating partners.

To begin registration, type PENZI and click Continue.</div>
              </div>

              <div className="activation-keyword-display">
                <span className="keyword-label">📱 Activation Keyword</span>
                <span className="keyword-code">PENZI</span>
                <span className="keyword-hint">Enter this keyword to activate the service</span>
              </div>

              <div className="activation-input-group">
                <label>SMS Command</label>
                <input
                  type="text"
                  value={activationKeyword}
                  onChange={(e) => setActivationKeyword(e.target.value.toUpperCase())}
                  placeholder="Type PENZI"
                  className="activation-input"
                  autoFocus
                />
              </div>

              <div className="activation-actions">
                <button
                  onClick={activateService}
                  disabled={isLoading || serverStatus === 'error'}
                  className="btn-activate"
                >
                  {isLoading ? '⏳ Activating...' : 'Continue'}
                </button>
                <button
                  onClick={() => setActivationKeyword('')}
                  className="btn-clear"
                >
                  Clear
                </button>
                <button
                  onClick={() => setShowLogoutModal(true)}
                  className="btn-exit"
                >
                  Exit
                </button>
              </div>

              {errorDetails && (
                <div className="error-details">
                  <p className="error-detail-text">💡 {errorDetails}</p>
                </div>
              )}

              {responseMessage && (
                <div className={`response-message ${isSuccess ? 'success' : 'error'}`}>
                  {responseMessage}
                </div>
              )}
            </>
          ) : (
            <div className="activation-success-container">
              <span className="activation-success-icon">✅</span>
              <p className="activation-success-text">Service Activated!</p>
              <p className="activation-success-sub">Welcome to PENZI Dating Service</p>
              <button onClick={proceedToRegistration} className="btn-start">
                🚀 Continue
              </button>
            </div>
          )}
        </div>
      </div>
    );
  };

  const renderSuccessScreen = () => {
    return (
      <div className="registration-container">
        <div className="registration-card">
          <div className="success-container">
            <span className="success-icon">✅</span>
            <h2 className="success-title">{successTitle}</h2>
            <p className="success-message">{successMessage}</p>
            <div className="success-actions">
              <button className="btn-primary" onClick={() => {
                setShowSuccessScreen(false);
                if (currentStep < 3) {
                  setCurrentStep(currentStep + 1);
                } else {
                  setIsLoggedIn(true);
                  setShowMainMenu(true);
                }
              }}>
                {currentStep < 3 ? 'Continue' : 'Main Menu'}
              </button>
              <button className="btn-exit" onClick={() => setShowLogoutModal(true)}>Exit</button>
            </div>
          </div>
        </div>
      </div>
    );
  };

  const renderUserExistsWarning = () => {
    return (
      <div className="registration-container">
        <div className="registration-card">
          <div className="registration-header">
            <span className="registration-icon">⚠️</span>
            <h1>Existing Account</h1>
            <p className="subtitle">An account already exists with this phone number</p>
          </div>

          <div className="user-exists-warning">
            <div className="warning-icon">⚠️</div>
            <div className="warning-content">
              <div className="warning-title">Account Already Exists</div>
              <div className="warning-text">An account already exists with this phone number.

Would you like to continue with your existing account?</div>
              <div className="warning-actions">
                <button className="btn-continue" onClick={() => {
                  setIsLoggedIn(true);
                  setShowMainMenu(true);
                  setUserExistsError(false);
                  setRegistrationError('');
                  addNotification('✅ Continuing with existing account');
                }}>
                  Continue
                </button>
                <button className="btn-recover" onClick={() => {
                  addNotification('🔐 Recovery process initiated', 'info');
                }}>
                  Recover Account
                </button>
                <button className="btn-cancel" onClick={() => {
                  setUserExistsError(false);
                  setRegistrationError('');
                  setCurrentStep(1);
                  addNotification('↩️ Returned to registration');
                }}>
                  Cancel
                </button>
              </div>
            </div>
          </div>

          <div className="registration-footer">
            <p>🔒 Your data is safe and private</p>
          </div>
        </div>
      </div>
    );
  };

  const renderWelcomeBack = () => {
    return (
      <div className="registration-container">
        <div className="registration-card">
          <div className="registration-header">
            <span className="registration-icon">👋</span>
            <h1>Welcome Back!</h1>
            <p className="subtitle">Your profile is active and ready to connect you with compatible partners.</p>
          </div>

          <div className="welcome-back-banner">
            <div className="welcome-back-icon">👤</div>
            <div className="welcome-back-text">
              <h3>{currentUser?.name || 'User'}</h3>
              <p>📱 {currentUser?.phone || myPhone}</p>
            </div>
            <div className="welcome-back-actions">
              <button className="btn-dashboard" onClick={() => {
                setIsLoggedIn(true);
                setShowWelcomeBack(false);
                setShowMainMenu(true);
              }}>
                Go to Dashboard
              </button>
              <button className="btn-messages" onClick={() => {
                setIsLoggedIn(true);
                setShowWelcomeBack(false);
                setActiveTab('chat');
              }}>
                View Messages
              </button>
            </div>
          </div>

          <div className="registration-actions">
            <button className="btn-primary" onClick={() => {
              setIsLoggedIn(true);
              setShowWelcomeBack(false);
              setShowMainMenu(true);
            }}>
              Continue to Dashboard
            </button>
            <button className="btn-exit" onClick={() => setShowLogoutModal(true)}>Exit</button>
          </div>

          <div className="registration-footer">
            <p>🔒 Your data is safe and private</p>
          </div>
        </div>
      </div>
    );
  };

  // ============================================
  // MAIN RETURN - This decides what screen to show
  // ============================================
  return (
    <div className="app">
      {renderNotifications()}
      {renderLogoutModal()}

      {showSuccessScreen ? (
        renderSuccessScreen()
      ) : userExistsError ? (
        renderUserExistsWarning()
      ) : showWelcomeBack && !isLoggedIn ? (
        renderWelcomeBack()
      ) : isLoggedIn ? (
        showMainMenu ? renderMainMenu() : renderDashboard()
      ) : (
        activationDone ? (
          isCompleteProfileStep ? (
            renderCompleteProfile()
          ) : (
            renderRegistrationStep()
          )
        ) : (
          renderActivationPage()
        )
      )}
    </div>
  );
}

export default App;
